func TestPolicy_Bluemonday(t *testing.T) {
	testSanitize(t, bluemondayTests)

	// Inputs too large for the table, from TestAllowDataURIImages and
	// TestIssue51, under the same license.
	files, err := filepath.Glob(filepath.Join("testdata", "bluemonday", "*.ugc.html"))
	require.NoError(t, err)
	require.NotEmpty(t, files)
	var tests []sanitizeTest
	for _, file := range files {
		name := strings.TrimSuffix(file, ".ugc.html")
		read := func(path string) string {
			b, err := os.ReadFile(path)
			require.NoError(t, err)
			return string(b)
		}
		tests = append(tests, sanitizeTest{
			name:         name,
			in:           read(name + ".html"),
			want:         read(file),
			wantMarkdown: read(name + ".markdown.html"),
		})
	}
	testSanitize(t, tests)
}

