func TestPolicy_Blank(t *testing.T) {
	p := NewPolicy(true, nil)
	for _, in := range []string{"", " ", " \n\t", "\u00a0"} {
		assert.Equal(t, in, string(p.AppendSanitized(nil, []byte(in))))
	}
}

func TestPolicy_AppendSanitized(t *testing.T) {
	p := NewPolicy(false, nil)
	dst := []byte("<p>")
	assert.Equal(t, `<p><b>x</b>`, string(p.AppendSanitized(dst, []byte(`<b onclick="y">x</b>`))))

	// The removed start tags of a call do not remove end tags of the next.
	assert.Equal(t, `x`, string(p.AppendSanitized(nil, []byte(`<a>x`))))
	assert.Equal(t, `x</a>`, string(p.AppendSanitized(nil, []byte(`x</a>`))))
}

func TestPolicy_Concurrent(t *testing.T) {
	ugc, markdown := NewPolicy(false, nil), NewPolicy(true, nil)
	var wg sync.WaitGroup
	for _, test := range bluemondayTests {
		wg.Add(1)
		go func() {
			defer wg.Done()
			wantMarkdown := test.wantMarkdown
			if wantMarkdown == "" {
				wantMarkdown = test.want
			}
			assert.Equal(t, test.want, string(ugc.AppendSanitized(nil, []byte(test.in))), "%q", test.in)
			assert.Equal(t, wantMarkdown, string(markdown.AppendSanitized(nil, []byte(test.in))), "%q", test.in)
		}()
	}
	wg.Wait()
}

// TestPolicy_CustomSchemes checks the custom URL schemes of the Markdown
// policy. Data URIs are checked even if the schemes list "data", unlike with
// bluemonday, whose outputs are in comments where they differ.
func TestPolicy_CustomSchemes(t *testing.T) {
	tests := []struct {
		schemes []string
		in      string
		want    string
	}{
		{nil, `<a href="ftp://example.com/">x</a>`, `x`},
		{[]string{"ftp"}, `<a href="ftp://example.com/">x</a>`, `<a href="ftp://example.com/" rel="nofollow">x</a>`},
		{[]string{"ftp"}, `<a href="FTP://example.com/">x</a>`, `<a href="ftp://example.com/" rel="nofollow">x</a>`},
		{[]string{"FTP"}, `<a href="ftp://example.com/">x</a>`, `<a href="ftp://example.com/" rel="nofollow">x</a>`},
		{[]string{"Ftp"}, `<a href="fTp://example.com/">x</a>`, `<a href="ftp://example.com/" rel="nofollow">x</a>`},
		{[]string{"ftp"}, `<img src="ftp://example.com/a.png">`, `<img src="ftp://example.com/a.png">`},
		{[]string{"ftp"}, `<blockquote cite="ftp://example.com/">x</blockquote>`, `<blockquote cite="ftp://example.com/">x</blockquote>`},
		{[]string{"ftp"}, `<area href="ftp://example.com/">`, `<area href="ftp://example.com/" rel="nofollow">`},
		{[]string{"ftp"}, `<a href="ftp://example.com/a b">x</a>`, `x`},
		{[]string{"ftp"}, `<a href="sftp://example.com/">x</a>`, `x`},
		{[]string{"ftp", "irc", "magnet"}, `<a href="irc://example.com/#c">a</a><a href="magnet:?xt=urn:x">b</a><a href="news:x">c</a>`, `<a href="irc://example.com/#c" rel="nofollow">a</a><a href="magnet:?xt=urn:x" rel="nofollow">b</a>c`},
		{[]string{"javascript"}, `<a href="javascript:alert(1)">x</a>`, `<a href="javascript:alert(1)" rel="nofollow">x</a>`},
		{[]string{"myapp"}, `<a href="myapp:open?x=1">x</a>`, `<a href="myapp:open?x=1" rel="nofollow">x</a>`},
		{[]string{"MyApp"}, `<a href="MYAPP:open?x=1">x</a>`, `<a href="myapp:open?x=1" rel="nofollow">x</a>`},
		{[]string{"my+app.v1"}, `<a href="my+app.v1:x">x</a>`, `<a href="my+app.v1:x" rel="nofollow">x</a>`},
		{[]string{"vscode"}, `<a href="vscode://file/a">x</a><a href="mailto:a@b">y</a><a href="/z">z</a>`, `<a href="vscode://file/a" rel="nofollow">x</a><a href="mailto:a@b" rel="nofollow">y</a><a href="/z" rel="nofollow">z</a>`},
		{[]string{""}, `<a href=":x">x</a>`, `x`},
		{[]string{"data"}, `<img src="data:image/png;base64,iVBORw0KGgo=">`, `<img src="data:image/png;base64,iVBORw0KGgo=">`},
		// bluemonday: <img src="data:text/html;base64,PHNjcmlwdD4=">
		{[]string{"data"}, `<img src="data:text/html;base64,PHNjcmlwdD4=">`, ``},
		// bluemonday: <a href="data:text/html,&lt;script&gt;alert(1)&lt;/script&gt;" rel="nofollow">x</a>
		{[]string{"data"}, `<a href="data:text/html,<script>alert(1)</script>">x</a>`, `x`},
		// bluemonday: <img src="data:image/svg+xml,&lt;svg onload=alert(1)&gt;">
		{[]string{"data"}, `<img src="data:image/svg+xml,<svg onload=alert(1)>">`, ``},
		// bluemonday: <img src="data:text/html;base64,PHNjcmlwdD4=">
		{[]string{"DATA"}, `<img src="data:text/html;base64,PHNjcmlwdD4=">`, ``},
		// bluemonday: <a href="data:text/plain,x" rel="nofollow">x</a><a href="ftp://a/" rel="nofollow">y</a>
		{[]string{"Data", "ftp"}, `<a href="data:text/plain,x">x</a><a href="ftp://a/">y</a>`, `x<a href="ftp://a/" rel="nofollow">y</a>`},
	}
	for _, test := range tests {
		p := NewPolicy(true, test.schemes)
		assert.Equal(t, test.want, string(p.AppendSanitized(nil, []byte(test.in))), "schemes %q: %q", test.schemes, test.in)
	}

	// The UGC policy ignores custom schemes.
	p := NewPolicy(false, []string{"ftp"})
	assert.Equal(t, `x`, string(p.AppendSanitized(nil, []byte(`<a href="ftp://example.com/">x</a>`))))
}

